<#
    ROXO TWEAKS
    Windows tweaks by Roxo.
    Run: right click -> Run with PowerShell (asks for Administrator by itself)
#>

# ---------------------------------------------------------------- Jurnal de pasi (pentru depanare)
$DebugLog = Join-Path $env:TEMP 'roxo-debug.log'
function Trace([string]$m) { try { Add-Content -Path $DebugLog -Value ("{0}  {1}" -f (Get-Date -Format 'HH:mm:ss'), $m) } catch {} }
Trace "--- start (PS $($PSVersionTable.PSVersion))"

# ---------------------------------------------------------------- Administrator
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
Trace "admin = $isAdmin"
if (-not $isAdmin) {
    if ($PSCommandPath) {
        Write-Host "Requesting Administrator rights..." -ForegroundColor Cyan
        try {
            Start-Process powershell -Verb RunAs -ArgumentList "-NoProfile -NoExit -ExecutionPolicy Bypass -STA -File `"$PSCommandPath`""
            Trace "relaunched as admin"
            exit
        } catch {
            Write-Host "Could not get Administrator rights: $($_.Exception.Message)" -ForegroundColor Red
            Read-Host "Press Enter to close"
            exit
        }
    } else {
        Write-Host "Run PowerShell as Administrator and try again." -ForegroundColor Yellow
        return
    }
}

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase

try {

$LogoB64 = ''

