          <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,12,0">
            <Button Name="BtnMin" Style="{StaticResource WinBtn}" Content="&#8212;"/>
            <Button Name="BtnClose" Style="{StaticResource WinBtn}" Content="&#10005;"/>
          </StackPanel>
        </Grid>

        <Grid Grid.Row="1" Margin="34,0,34,0">

          <!-- ===== OPTIMIZARI ===== -->
          <Grid Name="TweaksPanel">
            <Grid.RenderTransform><TranslateTransform Y="0"/></Grid.RenderTransform>
            <Grid.RowDefinitions>
              <RowDefinition Height="Auto"/>
              <RowDefinition Height="*"/>
              <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>
            <StackPanel Grid.Row="0">
              <TextBlock Text="Tweaks" FontSize="28" FontWeight="SemiBold" Foreground="#F6F0F8"/>
              <TextBlock Text="Pick what you want to change, then press Apply. Every tweak can be undone." FontSize="13" Foreground="#A596AD" Margin="0,4,0,0"/>
            </StackPanel>
            <ScrollViewer Name="TweakScroll" Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Margin="0,4,0,0">
              <StackPanel Name="TweakList" Margin="0,0,14,0"/>
            </ScrollViewer>
            <Grid Grid.Row="2" Margin="0,14,0,24">
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
              </Grid.ColumnDefinitions>
              <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                <CheckBox Name="ChkRestore" Style="{StaticResource Switch}" IsChecked="True" VerticalAlignment="Center">
                  <TextBlock Text="Create restore point first" FontSize="13" Foreground="#C9BCD0" VerticalAlignment="Center"/>
                </CheckBox>
                <Button Name="BtnRec" Style="{StaticResource Ghost}" Content="Recommended" Margin="22,0,0,0"/>
                <Button Name="BtnNone" Style="{StaticResource Ghost}" Content="Clear" Margin="8,0,0,0"/>
              </StackPanel>
              <StackPanel Grid.Column="1" Orientation="Horizontal">
                <Button Name="BtnUndo" Style="{StaticResource Ghost}" Content="Undo" Margin="0,0,8,0"/>
                <Button Name="BtnApply" Style="{StaticResource Primary}" Content="Apply"/>
              </StackPanel>
            </Grid>
          </Grid>

          <!-- ===== ACTUALIZARI ===== -->
          <Grid Name="UpdatesPanel" Visibility="Collapsed">
            <Grid.RenderTransform><TranslateTransform Y="0"/></Grid.RenderTransform>
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,14,14">
                <TextBlock Text="Updates" FontSize="28" FontWeight="SemiBold" Foreground="#F6F0F8"/>
                <TextBlock Text="Control how Windows Update behaves." FontSize="13" Foreground="#A596AD" Margin="0,4,0,18"/>

                <RadioButton Name="UpdDefault" Style="{StaticResource OptionCard}" GroupName="upd" IsChecked="True">
                  <StackPanel>
                    <TextBlock Text="Default" Style="{StaticResource TName}"/>
                    <TextBlock Text="Standard Windows behavior. Use this to go back to normal." Style="{StaticResource TDesc}"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton Name="UpdSecurity" Style="{StaticResource OptionCard}" GroupName="upd">
                  <StackPanel>
                    <TextBlock Text="Security only" Style="{StaticResource TName}"/>
                    <TextBlock Text="You still get security patches, while big feature updates are postponed for a year." Style="{StaticResource TDesc}"/>
                  </StackPanel>
                </RadioButton>
                <RadioButton Name="UpdDisable" Style="{StaticResource OptionCard}" GroupName="upd">
                  <StackPanel>
                    <TextBlock Text="Disabled" Style="{StaticResource TName}"/>
                    <TextBlock Text="Turns Windows Update off completely. You get no security patches either, so this is not recommended long term." Style="{StaticResource TDesc}"/>
                  </StackPanel>
                </RadioButton>

                <Button Name="BtnUpdMode" Style="{StaticResource Primary}" Content="Apply mode" HorizontalAlignment="Left" Margin="0,8,0,0"/>

                <TextBlock Text="Tools" Style="{StaticResource GroupTitle}" Margin="2,28,0,10"/>
                <WrapPanel>
                  <Button Name="BtnOpenWU" Style="{StaticResource Ghost}" Content="Open Windows Update" Margin="0,0,10,10"/>
                  <Button Name="BtnWinget" Style="{StaticResource Ghost}" Content="Update apps (winget)" Margin="0,0,10,10"/>
                  <Button Name="BtnRepairWU" Style="{StaticResource Ghost}" Content="Repair Windows Update" Margin="0,0,10,10"/>
                </WrapPanel>
              </StackPanel>
            </ScrollViewer>
          </Grid>
        </Grid>

      </Grid>
    </Grid>
  </Border>
</Window>
'@

Trace 'parsing XAML'
[xml]$xaml = $xamlText
$reader = New-Object System.Xml.XmlNodeReader $xaml
$Window = [Windows.Markup.XamlReader]::Load($reader)
Trace 'window created'
$xaml.SelectNodes("//*[@Name]") | ForEach-Object { $n = $_.GetAttribute('Name'); Set-Variable -Name $n -Value $Window.FindName($n) -Scope Script }
Trace 'controls bound'

# logo
try {
    $bytes = [Convert]::FromBase64String($LogoB64)
    $ms = New-Object IO.MemoryStream(,$bytes)
    $bi = New-Object Windows.Media.Imaging.BitmapImage
    $bi.BeginInit(); $bi.StreamSource = $ms; $bi.CacheOption = 'OnLoad'; $bi.EndInit(); $bi.Freeze()
    $LogoImg.Source = $bi
} catch {}

# ---------------------------------------------------------------- Ajutatoare
$LogDir  = Join-Path $env:LOCALAPPDATA 'RoxoTweaks'
$LogFile = Join-Path $LogDir 'roxo.log'
if (-not (Test-Path $LogDir)) { New-Item $LogDir -ItemType Directory -Force | Out-Null }

$script:Ready = $false
function Pump {
    if (-not $script:Ready) { return }
    $frame = New-Object System.Windows.Threading.DispatcherFrame
    $cb = { param($f) $f.Continue = $false }
    [void]$Window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Background,
        [System.Windows.Threading.DispatcherOperationCallback]{ param($f) $f.Continue = $false; $null }, $frame)
    [System.Windows.Threading.Dispatcher]::PushFrame($frame)
}

function Write-Log([string]$msg) {
    $line = "{0}  {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg
    try { Add-Content -Path $LogFile -Value $line -Encoding UTF8 } catch {}
    Pump
}

function Notify([string]$m) { try { [void][System.Windows.MessageBox]::Show($Window, $m, 'Roxo Tweaks') } catch {} }


# ---------------------------------------------------------------- Animatii
function Convert-Color([string]$hex) { [System.Windows.Media.ColorConverter]::ConvertFromString($hex) }

function Fade-Brush($brush, [string]$hex, [int]$ms = 160) {
    try {
        $a = New-Object System.Windows.Media.Animation.ColorAnimation
        $a.To = Convert-Color $hex
        $a.Duration = [TimeSpan]::FromMilliseconds($ms)
        $brush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $a)
    } catch {}
}

function Show-Panel($panel) {
    try {
        $ease = New-Object System.Windows.Media.Animation.CubicEase
        $ease.EasingMode = 'EaseOut'
        $fa = New-Object System.Windows.Media.Animation.DoubleAnimation
        $fa.From = 0; $fa.To = 1; $fa.Duration = [TimeSpan]::FromMilliseconds(280)
        $panel.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fa)
        $ta = New-Object System.Windows.Media.Animation.DoubleAnimation
        $ta.From = 14; $ta.To = 0; $ta.Duration = [TimeSpan]::FromMilliseconds(380); $ta.EasingFunction = $ease
        $panel.RenderTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $ta)
    } catch {}
}

function Play-Cascade {
    $i = 0
    foreach ($el in $TweakList.Children) {
        try {
            $delay = [TimeSpan]::FromMilliseconds(35 * $i)
            $ease = New-Object System.Windows.Media.Animation.CubicEase
            $ease.EasingMode = 'EaseOut'
            $tt = New-Object System.Windows.Media.TranslateTransform -ArgumentList 0, 16
            $el.RenderTransform = $tt
            $fa = New-Object System.Windows.Media.Animation.DoubleAnimation
            $fa.To = 1; $fa.Duration = [TimeSpan]::FromMilliseconds(380); $fa.BeginTime = $delay
            $ta = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ta.To = 0; $ta.Duration = [TimeSpan]::FromMilliseconds(520); $ta.BeginTime = $delay; $ta.EasingFunction = $ease
            $el.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fa)
            $tt.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $ta)
        } catch { $el.Opacity = 1 }
        $i++
    }
}

function Set-Reg($Path, $Name, $Value, $Type = 'DWord') {
    if (-not (Test-Path $Path)) { New-Item $Path -Force | Out-Null }
    New-ItemProperty -Path $Path -Name $Name -Value $Value -PropertyType $Type -Force | Out-Null
}
function Del-Reg($Path, $Name) { Remove-ItemProperty -Path $Path -Name $Name -ErrorAction SilentlyContinue }

function New-RoxoRestorePoint {
    Write-Log "Creating restore point..."
    try {
        Enable-ComputerRestore -Drive "$env:SystemDrive\" -ErrorAction SilentlyContinue
        Set-Reg 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore' 'SystemRestorePointCreationFrequency' 0
        Checkpoint-Computer -Description 'Roxo Tweaks' -RestorePointType MODIFY_SETTINGS -ErrorAction Stop
        Write-Log "Restore point created."
    } catch {
        Write-Log "Could not create restore point: $($_.Exception.Message)"
    }
}

function Restart-Explorer { Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue }

# ---------------------------------------------------------------- Lista de optimizari
$CtxKey = 'HKCU:\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}'
$CDM    = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager'
$Adv    = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'

$Tweaks = @(
    # ---- Confidentialitate
    @{ Id='telemetry'; Cat='Privacy'; Rec=$true; Name='Disable telemetry';
       Desc='Stops sending diagnostic data to Microsoft and turns off the DiagTrack service.';
       Apply={ Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection' 'AllowTelemetry' 0
               foreach($s in 'DiagTrack','dmwappushservice'){ Stop-Service $s -Force -ErrorAction SilentlyContinue; Set-Service $s -StartupType Disabled -ErrorAction SilentlyContinue } };
       Undo={ Del-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection' 'AllowTelemetry'
              Set-Service DiagTrack -StartupType Automatic -ErrorAction SilentlyContinue; Start-Service DiagTrack -ErrorAction SilentlyContinue
              Set-Service dmwappushservice -StartupType Manual -ErrorAction SilentlyContinue } },

    @{ Id='activity'; Cat='Privacy'; Rec=$true; Name='Disable activity history';
       Desc='Windows stops keeping track of the apps and files you open.';
       Apply={ $p='HKLM:\SOFTWARE\Policies\Microsoft\Windows\System'
               Set-Reg $p 'EnableActivityFeed' 0; Set-Reg $p 'PublishUserActivities' 0; Set-Reg $p 'UploadUserActivities' 0 };
       Undo={ $p='HKLM:\SOFTWARE\Policies\Microsoft\Windows\System'
              Del-Reg $p 'EnableActivityFeed'; Del-Reg $p 'PublishUserActivities'; Del-Reg $p 'UploadUserActivities' } },

    @{ Id='adid'; Cat='Privacy'; Rec=$true; Name='Disable advertising ID';
       Desc='Apps can no longer use a unique identifier for targeted ads.';
       Apply={ Set-Reg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo' 'Enabled' 0 };
       Undo={ Set-Reg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo' 'Enabled' 1 } },

    @{ Id='consumer'; Cat='Privacy'; Rec=$true; Name='Remove suggestions and promoted apps';
       Desc='No ads in Start and no automatic installs of sponsored apps.';
       Apply={ Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' 'DisableWindowsConsumerFeatures' 1
               foreach($n in 'SubscribedContent-338388Enabled','SubscribedContent-338389Enabled','SubscribedContent-353698Enabled','SystemPaneSuggestionsEnabled','SilentInstalledAppsEnabled'){ Set-Reg $CDM $n 0 } };
       Undo={ Del-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' 'DisableWindowsConsumerFeatures'
              foreach($n in 'SubscribedContent-338388Enabled','SubscribedContent-338389Enabled','SubscribedContent-353698Enabled','SystemPaneSuggestionsEnabled','SilentInstalledAppsEnabled'){ Set-Reg $CDM $n 1 } } },

    @{ Id='bing'; Cat='Privacy'; Rec=$true; Name='Disable web search in Start';
       Desc='Start search only looks on your PC, with no Bing results.';
       Apply={ Set-Reg 'HKCU:\Software\Policies\Microsoft\Windows\Explorer' 'DisableSearchBoxSuggestions' 1 };
       Undo={ Del-Reg 'HKCU:\Software\Policies\Microsoft\Windows\Explorer' 'DisableSearchBoxSuggestions' } },

    @{ Id='copilot'; Cat='Privacy'; Rec=$false; Name='Disable Copilot';
       Desc='Hides and turns off the Copilot assistant in Windows.';
       Apply={ Set-Reg 'HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot' 'TurnOffWindowsCopilot' 1 };
       Undo={ Del-Reg 'HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot' 'TurnOffWindowsCopilot' } },

    # ---- Performanta
    @{ Id='power'; Cat='Performance'; Rec=$false; Name='Ultimate Performance power plan';
       Desc='Maximum performance. Best on desktops, uses more battery on laptops.';
       Apply={ $o = powercfg -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 | Out-String
               if($o -match '([0-9a-fA-F\-]{36})'){ powercfg -setactive $matches[1] } else { Write-Log 'The Ultimate plan is not available on this Windows edition.' } };
       Undo={ powercfg -setactive 381b4222-f694-41f0-9685-ff5bb260df2e } },

    @{ Id='gamedvr'; Cat='Performance'; Rec=$true; Name='Disable Game DVR';
       Desc='Stops Xbox Game Bar background recording, which can lower FPS.';
       Apply={ Set-Reg 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 0
               Set-Reg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled' 0 };
       Undo={ Set-Reg 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 1
              Set-Reg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled' 1 } },

    @{ Id='startdelay'; Cat='Performance'; Rec=$true; Name='Remove startup delay';
       Desc='Startup apps launch right away, without the artificial delay Windows adds.';
       Apply={ Set-Reg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Serialize' 'StartupDelayInMSec' 0 };
       Undo={ Del-Reg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Serialize' 'StartupDelayInMSec' } },

    @{ Id='menudelay'; Cat='Performance'; Rec=$true; Name='Instant menus';
       Desc='Removes the pause before submenus appear. Takes effect after you sign out and back in.';
       Apply={ Set-Reg 'HKCU:\Control Panel\Desktop' 'MenuShowDelay' '0' 'String' };
       Undo={ Set-Reg 'HKCU:\Control Panel\Desktop' 'MenuShowDelay' '400' 'String' } },

    @{ Id='transparency'; Cat='Performance'; Rec=$false; Name='Disable transparency';
       Desc='No glass effects in Start and the taskbar. Less load on the GPU.';
       Apply={ Set-Reg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' 'EnableTransparency' 0 };
       Undo={ Set-Reg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' 'EnableTransparency' 1 } },

    @{ Id='mouse'; Cat='Performance'; Rec=$false; Name='Disable mouse acceleration';
       Desc='1:1 cursor movement, preferred in games. Takes effect after you sign out and back in.';
       Apply={ $p='HKCU:\Control Panel\Mouse'; Set-Reg $p 'MouseSpeed' '0' 'String'; Set-Reg $p 'MouseThreshold1' '0' 'String'; Set-Reg $p 'MouseThreshold2' '0' 'String' };
       Undo={ $p='HKCU:\Control Panel\Mouse'; Set-Reg $p 'MouseSpeed' '1' 'String'; Set-Reg $p 'MouseThreshold1' '6' 'String'; Set-Reg $p 'MouseThreshold2' '10' 'String' } },

    @{ Id='hibernate'; Cat='Performance'; Rec=$false; Name='Disable hibernation';
       Desc='Deletes hiberfil.sys and frees several GB. Also disables Fast Startup.';
       Apply={ powercfg /hibernate off };
       Undo={ powercfg /hibernate on } },

    # ---- Aspect si Explorer
    @{ Id='fileext'; Cat='Appearance & Explorer'; Rec=$true; Name='Show file extensions';
       Desc='See .exe, .png, .txt and so on at the end of file names.';
       Apply={ Set-Reg $Adv 'HideFileExt' 0; $script:NeedExplorer = $true };
       Undo={ Set-Reg $Adv 'HideFileExt' 1; $script:NeedExplorer = $true } },

    @{ Id='hidden'; Cat='Appearance & Explorer'; Rec=$false; Name='Show hidden files';
       Desc='Explorer also shows files and folders marked as hidden.';
       Apply={ Set-Reg $Adv 'Hidden' 1; $script:NeedExplorer = $true };
       Undo={ Set-Reg $Adv 'Hidden' 2; $script:NeedExplorer = $true } },

    @{ Id='ctxmenu'; Cat='Appearance & Explorer'; Rec=$false; Name='Classic right-click menu (Windows 11)';
       Desc='Brings back the full menu, without "Show more options". Explorer restarts automatically.';
       Apply={ New-Item -Path "$CtxKey\InprocServer32" -Force | Out-Null
               Set-ItemProperty -Path "$CtxKey\InprocServer32" -Name '(default)' -Value ''
               $script:NeedExplorer = $true };
       Undo={ Remove-Item -Path $CtxKey -Recurse -Force -ErrorAction SilentlyContinue; $script:NeedExplorer = $true } },

    @{ Id='dark'; Cat='Appearance & Explorer'; Rec=$false; Name='Dark mode';
       Desc='Applies the dark theme to Windows and apps.';
       Apply={ $p='HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize'; Set-Reg $p 'AppsUseLightTheme' 0; Set-Reg $p 'SystemUsesLightTheme' 0 };
       Undo={ $p='HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize'; Set-Reg $p 'AppsUseLightTheme' 1; Set-Reg $p 'SystemUsesLightTheme' 1 } },

    # ---- Curatenie
    @{ Id='temp'; Cat='Cleanup'; Rec=$true; NoUndo=$true; Name='Delete temporary files';
       Desc='Empties %TEMP% and C:\Windows\Temp. Cannot be undone, but nothing important is affected.';
       Apply={ Remove-Item "$env:TEMP\*" -Recurse -Force -ErrorAction SilentlyContinue
               Remove-Item "$env:windir\Temp\*" -Recurse -Force -ErrorAction SilentlyContinue };
       Undo={ Write-Log 'Deleting temporary files cannot be undone.' } },

    @{ Id='recycle'; Cat='Cleanup'; Rec=$false; NoUndo=$true; Name='Empty the Recycle Bin';
       Desc='Permanently deletes everything in the Recycle Bin. Cannot be undone.';
       Apply={ Clear-RecycleBin -Force -ErrorAction SilentlyContinue };
       Undo={ Write-Log 'Emptying the Recycle Bin cannot be undone.' } }
)

# ---------------------------------------------------------------- Construieste lista in UI
$Checks = @{}
$lastCat = ''
foreach ($t in $Tweaks) {
    if ($t.Cat -ne $lastCat) {
        $h = New-Object Windows.Controls.TextBlock
        $h.Text = $t.Cat
        $h.Style = $Window.FindResource('GroupTitle')
        $h.Opacity = 0
        [void]$TweakList.Children.Add($h)
        $lastCat = $t.Cat
    }
    $card = New-Object Windows.Controls.Border
    $card.Style = $Window.FindResource('Card')
    $card.Background  = New-Object System.Windows.Media.SolidColorBrush (Convert-Color '#231829')
    $card.BorderBrush = New-Object System.Windows.Media.SolidColorBrush (Convert-Color '#3D2B4A')
    $card.Opacity = 0

    $cb = New-Object Windows.Controls.CheckBox
    $cb.Style = $Window.FindResource('Switch')
    $cb.IsChecked = $false

    $sp = New-Object Windows.Controls.StackPanel
    $n = New-Object Windows.Controls.TextBlock; $n.Text = $t.Name; $n.Style = $Window.FindResource('TName')
    $d = New-Object Windows.Controls.TextBlock; $d.Text = $t.Desc; $d.Style = $Window.FindResource('TDesc')
    [void]$sp.Children.Add($n); [void]$sp.Children.Add($d)
    $cb.Content = $sp

    $card.Child = $cb
    $cb.Tag = $card
    $card.Add_MouseEnter({ param($s, $e)
        Fade-Brush $s.Background '#2B1E35' 150
        Fade-Brush $s.BorderBrush $(if ($s.Child.IsChecked) { '#8FBF9F' } else { '#5A4570' }) 150
    })
    $card.Add_MouseLeave({ param($s, $e)
        Fade-Brush $s.Background '#231829' 220
        Fade-Brush $s.BorderBrush $(if ($s.Child.IsChecked) { '#4F7A5F' } else { '#3D2B4A' }) 220
    })
    $cb.Add_Checked({   param($s, $e) Fade-Brush $s.Tag.BorderBrush '#4F7A5F' 220 })
    $cb.Add_Unchecked({ param($s, $e) Fade-Brush $s.Tag.BorderBrush '#3D2B4A' 220 })
    [void]$TweakList.Children.Add($card)
    $Checks[$t.Id] = $cb
}

Trace 'tweak list built'
# ---------------------------------------------------------------- Actiuni
function Set-Busy([bool]$busy) {
    foreach ($b in $BtnApply,$BtnUndo,$BtnRec,$BtnNone,$BtnUpdMode,$BtnOpenWU,$BtnWinget,$BtnRepairWU) { $b.IsEnabled = -not $busy }
    Pump
}

function Invoke-Selected([string]$mode) {
    $sel = $Tweaks | Where-Object { $Checks[$_.Id].IsChecked }
    if (-not $sel) { Notify 'Nothing selected. Switch on at least one tweak first.'; return }

    Set-Busy $true
    $script:NeedExplorer = $false
    if ($mode -eq 'Apply' -and $ChkRestore.IsChecked) { New-RoxoRestorePoint }

    foreach ($t in $sel) {
        $verb = if ($mode -eq 'Apply') { 'Applying' } else { 'Undoing' }
        Write-Log "$verb`: $($t.Name)"
        try {
            if ($mode -eq 'Apply') { & $t.Apply } else { & $t.Undo }
        } catch {
            Write-Log "  Error: $($_.Exception.Message)"
        }
    }
    if ($script:NeedExplorer) { Write-Log 'Restarting Explorer...'; Restart-Explorer }
    Write-Log 'Done.'
    Set-Busy $false
    Notify 'Done. Some changes need a sign-out or restart to take effect.'
}

$BtnApply.Add_Click({ Invoke-Selected 'Apply' })
$BtnUndo.Add_Click({  Invoke-Selected 'Undo'  })
$BtnRec.Add_Click({  foreach($t in $Tweaks){ $Checks[$t.Id].IsChecked = [bool]$t.Rec } })
$BtnNone.Add_Click({ foreach($t in $Tweaks){ $Checks[$t.Id].IsChecked = $false } })

# ---- Actualizari
$WU = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
$AU = "$WU\AU"

$BtnUpdMode.Add_Click({
    Set-Busy $true
    try {
        if ($UpdDefault.IsChecked) {
            Write-Log 'Updates: restoring defaults...'
            Del-Reg $AU 'NoAutoUpdate'
            foreach($n in 'DeferFeatureUpdates','DeferFeatureUpdatesPeriodInDays','DeferQualityUpdates','DeferQualityUpdatesPeriodInDays'){ Del-Reg $WU $n }
            Set-Service wuauserv -StartupType Manual -ErrorAction SilentlyContinue
            Set-Service UsoSvc  -StartupType Manual -ErrorAction SilentlyContinue
            Start-Service wuauserv -ErrorAction SilentlyContinue
        }
        elseif ($UpdSecurity.IsChecked) {
            Write-Log 'Updates: security only...'
            Del-Reg $AU 'NoAutoUpdate'
            Set-Reg $WU 'DeferFeatureUpdates' 1
            Set-Reg $WU 'DeferFeatureUpdatesPeriodInDays' 365
            Set-Reg $WU 'DeferQualityUpdates' 1
            Set-Reg $WU 'DeferQualityUpdatesPeriodInDays' 4
            Set-Service wuauserv -StartupType Manual -ErrorAction SilentlyContinue
        }
        else {
            Write-Log 'Updates: disabling Windows Update...'
            Set-Reg $AU 'NoAutoUpdate' 1
            foreach($s in 'wuauserv','UsoSvc'){ Stop-Service $s -Force -ErrorAction SilentlyContinue; Set-Service $s -StartupType Disabled -ErrorAction SilentlyContinue }
        }
        Write-Log 'Done.'
        Notify 'Update mode applied.'
    } catch { Write-Log "Error: $($_.Exception.Message)" }
    Set-Busy $false
})

$BtnOpenWU.Add_Click({ Start-Process 'ms-settings:windowsupdate' })

$BtnWinget.Add_Click({
    if (-not (Get-Command winget -ErrorAction SilentlyContinue)) { Write-Log 'winget is not installed on this PC.'; return }
    Write-Log 'Updating apps in a separate window...'
    Start-Process powershell -ArgumentList '-NoExit','-Command','winget upgrade --all --accept-source-agreements --accept-package-agreements'
})

$BtnRepairWU.Add_Click({
    Set-Busy $true
    Write-Log 'Repairing Windows Update...'
    try {
        $svcs = 'wuauserv','bits','cryptsvc','UsoSvc'
        foreach($s in $svcs){ Stop-Service $s -Force -ErrorAction SilentlyContinue }
        $sd = "$env:windir\SoftwareDistribution"
        if (Test-Path "$sd.old") { Remove-Item "$sd.old" -Recurse -Force -ErrorAction SilentlyContinue }
        if (Test-Path $sd) { Rename-Item $sd "$sd.old" -ErrorAction SilentlyContinue }
        foreach($s in $svcs){ Start-Service $s -ErrorAction SilentlyContinue }
        Write-Log 'Done. Try Windows Update again.'
        Notify 'Windows Update repaired. Try checking for updates again.'
    } catch { Write-Log "Error: $($_.Exception.Message)" }
    Set-Busy $false
})

# ---------------------------------------------------------------- Navigare si fereastra
$NavTweaks.Add_Checked({  $TweaksPanel.Visibility = 'Visible';   $UpdatesPanel.Visibility = 'Collapsed'; Show-Panel $TweaksPanel })
$NavUpdates.Add_Checked({ $TweaksPanel.Visibility = 'Collapsed'; $UpdatesPanel.Visibility = 'Visible'; Show-Panel $UpdatesPanel })

$TitleBar.Add_MouseLeftButtonDown({ $Window.DragMove() })
$BtnMin.Add_Click({ $Window.WindowState = 'Minimized' })
$BtnClose.Add_Click({ $Window.Close() })

$Window.Add_ContentRendered({
    $script:Ready = $true
    $Window.Activate() | Out-Null
    Trace 'window shown'
    try { Play-Cascade } catch { foreach ($el in $TweakList.Children) { $el.Opacity = 1 } }
})

Write-Log 'Welcome to Roxo Tweaks.'
Trace 'showing window'
[void]$Window.ShowDialog()
Trace 'window closed'

} catch {
    $err = $_ | Out-String
    try { Add-Content -Path (Join-Path $env:TEMP 'roxo-error.log') -Value $err } catch {}
    Write-Host ""
    Write-Host "Roxo Tweaks hit an error:" -ForegroundColor Red
    Write-Host $err -ForegroundColor Yellow
    try { [void][Windows.MessageBox]::Show($err, 'Roxo Tweaks - error') } catch {}
    Read-Host "Press Enter to close"
}
